//! The brief — every capability in this feature, folded into ONE ranked list of what to do.
//!
//! Twenty-five modules each produce their own answer and nothing composed them, so anything asked to
//! "use the finance system" had to re-derive the same synthesis every time. This is that synthesis,
//! once, as data.
//!
//! **It composes, it does not recompute.** Every input is another capability's OUTPUT. Nothing here
//! recalculates a runway or re-prices a transfer, because a second implementation of a number is a
//! second answer to the same question, and the two will disagree eventually.
//!
//! # Two tiers, because one ordering cannot hold both
//!
//! - **Do not miss** — things with a date. A minimum payment due Friday is not comparable to a
//!   $5,000 opportunity by any rate; it is comparable to a late fee and a credit event. Sorted by
//!   WHEN.
//! - **Best return** — everything else, sorted by what it is worth PER HOUR OF YOUR EFFORT. A $40
//!   fee waiver that takes a ten-minute phone call beats a $5,000 grant that takes eighty hours, and
//!   ranking by size alone gets that exactly backwards.
//!
//! **Absent is not zero**, and this is the discipline that makes the brief trustworthy. A capability
//! that was never run contributes NOTHING and is NAMED as missing. A brief reporting "$0 available
//! in fee waivers" when the fee audit never ran is a lie, and it is the specific lie that would make
//! somebody stop looking.
use crate::money::{money, Currency, Money};
use crate::negotiate::{Ask, NegotiationCase};
use crate::obligations::{add_days, due_between, Confidence, ObligationCalendar, ObligationKind};
use crate::opportunity::{Assessment, Verdict};
use crate::position::Position;
use crate::priority::Priority;
use crate::runway::{survives_horizon, Runway};
use crate::transfer::TransferAssessment;
use crate::viable::ViableIncome;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tier {
    DoNotMiss,
    BestReturn,
    Blocked,
}

impl Tier {
    pub fn label(self) -> &'static str {
        match self {
            Tier::DoNotMiss => "do-not-miss",
            Tier::BestReturn => "best-return",
            Tier::Blocked => "blocked",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Action {
    pub id: String,
    pub title: String,
    /// Which capability produced it, so a figure can be traced back and checked.
    pub source: &'static str,
    pub tier: Tier,
    /// `YYYY-MM-DD`, for anything with a date.
    pub by: Option<String>,
    pub worth: Option<Money>,
    /// What the worth MEANS — a year of interest, a one-off, an expectation. Without this the number
    /// is not comparable to the one under it.
    pub worth_basis: Option<&'static str>,
    pub effort_hours: Option<f64>,
    /// `worth ÷ effort`. ABSENT when either is, and it sorts LAST rather than as zero.
    pub per_hour: Option<Money>,
    pub why: String,
    /// True when this rests on something incomplete or unchecked.
    pub provisional: bool,
    pub blocked_by: Option<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Brief {
    pub as_of: String,
    pub currency: Currency,
    /// Where you stand, in one sentence.
    pub headline: String,
    pub do_not_miss: Vec<Action>,
    pub best_return: Vec<Action>,
    pub blocked: Vec<Action>,
    /// Capabilities that produced nothing, BY NAME — the difference between "nothing to do" and
    /// "nothing looked".
    pub absent: Vec<String>,
    /// What every figure above is standing on.
    pub caveats: Vec<String>,
}

#[derive(Default)]
pub struct BriefInput<'a> {
    /// `YYYY-MM-DD`. Passed in, never a clock.
    pub as_of: &'a str,
    pub currency: Option<Currency>,
    pub position: Option<&'a Position>,
    pub runway: Option<&'a Runway>,
    pub viable: Option<&'a ViableIncome>,
    pub priority: Option<&'a Priority>,
    pub negotiation: Option<&'a [NegotiationCase]>,
    pub transfers: Option<&'a [TransferAssessment]>,
    pub opportunities: Option<&'a [Assessment]>,
    pub calendar: Option<&'a ObligationCalendar>,
    /// How far ahead a dated obligation counts as urgent.
    pub horizon_days: i64,
    /// Effort defaults, NAMED rather than buried, because they drive the whole ranking.
    pub call_hours: f64,
    pub transfer_hours: f64,
}

impl<'a> BriefInput<'a> {
    pub fn new(as_of: &'a str, currency: Currency) -> Self {
        BriefInput { as_of, currency: Some(currency), horizon_days: 30, call_hours: 0.5, transfer_hours: 1.0, ..Default::default() }
    }

    fn cur(&self) -> Currency {
        self.currency.unwrap_or(Currency::USD)
    }
}

/// `worth ÷ effort`, or NONE — never zero, which would sort a priceless thing among the worthless.
fn per_hour_of(worth: Option<Money>, hours: f64, currency: Currency) -> Option<Money> {
    let w = worth?;
    if hours <= 0.0 {
        return None;
    }
    Some(money((w.minor as f64 / hours).round() as i64, currency))
}

pub fn build_brief(input: &BriefInput) -> Brief {
    let currency = input.cur();
    let mut actions: Vec<Action> = Vec::new();
    let mut absent: Vec<String> = Vec::new();
    let mut caveats: Vec<String> = Vec::new();

    // PROVISIONAL propagates from the bottom. Everything derived from an incomplete position or an
    // unverified ledger is itself provisional, and saying so once at the top is not enough — the
    // reader acts on individual LINES.
    let unverified = input.position.map(|p| p.provenance.starts_with("UNVERIFIED")).unwrap_or(false);
    let provisional = input.position.is_none_or(|p| !p.complete) || unverified;
    if unverified {
        caveats.push(format!("the ledger under this was never reconciled: {}", input.position.map(|p| p.provenance.as_str()).unwrap_or("")));
    }
    if let Some(p) = input.position {
        if !p.complete {
            caveats.push(format!("the position is incomplete — {} unresolved issue(s), so every figure below inherits them", p.problems.len()));
        }
    }

    // ── DO NOT MISS ──────────────────────────────────────────────────────────────────────────────
    match input.calendar {
        Some(cal) => {
            for o in due_between(cal, input.as_of, &add_days(input.as_of, input.horizon_days)) {
                let assumed = o.confidence == Confidence::Assumed;
                actions.push(Action {
                    id: format!("due:{}:{}:{}", o.account, o.date, o.label),
                    title: format!("{} — {} due", o.label, o.amount.minor),
                    source: "obligations",
                    tier: Tier::DoNotMiss,
                    by: Some(o.date.clone()),
                    worth: Some(o.amount),
                    worth_basis: Some("the amount due"),
                    // The assumed-date note applies to a MINIMUM too, and especially to one:
                    // `obligations` places an unknown due day on the 1st — the earliest it could
                    // plausibly fall — so the date is the conservative guess rather than a fact, and
                    // the one obligation that must not be late is where that matters most.
                    why: format!(
                        "{}{}",
                        if o.kind == ObligationKind::Minimum {
                            "a missed minimum is a late fee, a penalty rate on the whole balance, and a credit event that outlasts the month"
                        } else {
                            "a standing obligation"
                        },
                        if assumed { " — the DATE is assumed, not observed" } else { "" }
                    ),
                    provisional: provisional || assumed,
                    effort_hours: None,
                    per_hour: None,
                    blocked_by: None,
                });
            }
        }
        None => absent.push("obligations — no calendar was built, so nothing here knows what is due".to_string()),
    }

    // ── BEST RETURN ──────────────────────────────────────────────────────────────────────────────
    match input.negotiation {
        Some(cases) => {
            // A hardship case is NOT a best-return item and is handled below as dated work — it has
            // to happen before a missed payment, and ranking it by expectation per hour would bury it.
            for c in cases.iter().filter(|x| x.ask != Ask::HardshipPlan) {
                let worth = c.annual_value_if_won;
                actions.push(Action {
                    id: format!("call:{}:{}", c.account, c.ask.label()),
                    title: format!("{} — ask for a {}", c.institution, c.ask.label().replace('-', " ")),
                    source: "negotiate",
                    tier: Tier::BestReturn,
                    by: None,
                    worth: Some(worth),
                    worth_basis: Some(if c.ask == Ask::FeeWaiver { "the fee, one-off" } else { "a year, if granted" }),
                    effort_hours: Some(input.call_hours),
                    per_hour: per_hour_of(Some(worth), input.call_hours, currency),
                    why: c.why.clone(),
                    provisional,
                    blocked_by: None,
                });
            }
        }
        None => absent.push("negotiate — no call list was prepared".to_string()),
    }

    match input.transfers {
        Some(ts) => {
            for t in ts.iter().filter(|x| x.worth_it) {
                actions.push(Action {
                    id: format!("transfer:{}:{}", t.source_account, t.offer_id),
                    title: format!("move {} from {} to {}", t.moved.minor, t.source_account, t.institution),
                    source: "transfer",
                    tier: Tier::BestReturn,
                    by: None,
                    worth: Some(t.net_benefit),
                    worth_basis: Some("interest avoided over the promotion, less the fee"),
                    effort_hours: Some(input.transfer_hours),
                    per_hour: per_hour_of(Some(t.net_benefit), input.transfer_hours, currency),
                    why: format!(
                        "{} of interest avoided against a {} fee — and the balance must be gone before the promotion ends",
                        t.interest_avoided.minor, t.fee.minor
                    ),
                    provisional,
                    blocked_by: None,
                });
            }
            if !ts.is_empty() && !ts.iter().any(|x| x.worth_it) {
                // A RESULT, not a gap — and the distinction is the whole point of the absent list.
                caveats.push(format!("{} transfer offer(s) were priced and NONE beat its fee — that is a result, not a gap", ts.len()));
            }
        }
        None => absent.push("transfer — no offers were priced".to_string()),
    }

    match input.opportunities {
        Some(os) => {
            for a in os.iter().filter(|x| x.verdict == Verdict::Biddable && x.beats_contracting) {
                actions.push(Action {
                    id: format!("bid:{}", a.opportunity.id),
                    title: format!("bid: {}", a.opportunity.title),
                    source: "opportunity",
                    tier: Tier::BestReturn,
                    by: Some(a.opportunity.closes.clone()),
                    worth: a.expected,
                    worth_basis: Some("expectation — award × hit rate, not revenue"),
                    effort_hours: Some(a.opportunity.bid_hours),
                    per_hour: a.per_hour,
                    why: format!("beats billing the same {}h", a.opportunity.bid_hours),
                    provisional,
                    blocked_by: None,
                });
            }
        }
        None => absent.push("opportunity — no funding sources were scanned".to_string()),
    }

    match input.priority {
        Some(p) => {
            if let Some(target) = &p.target {
                if p.to_debt.minor > 0 {
                    actions.push(Action {
                        id: format!("pay:{}", target.account),
                        title: format!("put {} above the minimum into {}", p.to_debt.minor, target.institution),
                        source: "priority",
                        tier: Tier::BestReturn,
                        by: None,
                        worth: Some(p.to_debt),
                        worth_basis: Some("the payment itself — the return is the rate it stops accruing"),
                        effort_hours: None,
                        per_hour: None,
                        why: target.why.clone(),
                        provisional,
                        blocked_by: None,
                    });
                }
            }
            if p.to_buffer.minor != 0 {
                actions.push(Action {
                    id: "buffer".to_string(),
                    title: format!("put {} into the emergency buffer", p.to_buffer.minor),
                    source: "priority",
                    tier: Tier::BestReturn,
                    by: None,
                    worth: Some(p.to_buffer),
                    worth_basis: Some("the amount set aside"),
                    effort_hours: None,
                    per_hour: None,
                    why: "a buffer beats the rate until it exists — without one the next unplanned bill goes back onto the highest-rate card".to_string(),
                    provisional,
                    blocked_by: None,
                });
            }
        }
        None => absent.push("priority — nothing decided where this month's spare money goes".to_string()),
    }

    // ── BLOCKED ──────────────────────────────────────────────────────────────────────────────────
    if let Some(cases) = input.negotiation {
        for c in cases.iter().filter(|x| x.ask == Ask::HardshipPlan) {
            // Not blocked in the sense of impossible — DATED, in the sense that it must happen
            // before something else, and the something else is a missed payment.
            actions.push(Action {
                id: format!("hardship:{}", c.account),
                title: format!("{} — hardship arrangement, BEFORE a payment is missed", c.institution),
                source: "negotiate",
                tier: Tier::DoNotMiss,
                by: None,
                worth: Some(c.annual_value_if_won),
                worth_basis: Some("a year, if granted"),
                effort_hours: Some(input.call_hours),
                per_hour: per_hour_of(Some(c.annual_value_if_won), input.call_hours, currency),
                why: c.urgency.clone().unwrap_or_else(|| c.why.clone()),
                provisional,
                blocked_by: None,
            });
        }
    }
    if let Some(os) = input.opportunities {
        for a in os.iter().filter(|x| x.verdict == Verdict::Ineligible && !x.unmet.is_empty()) {
            actions.push(Action {
                id: format!("unblock:{}", a.opportunity.id),
                title: format!("cannot bid {}", a.opportunity.title),
                source: "opportunity",
                tier: Tier::Blocked,
                by: None,
                worth: None,
                worth_basis: None,
                effort_hours: None,
                per_hour: None,
                why: a.why.clone().unwrap_or_else(|| "ineligible".to_string()),
                provisional,
                blocked_by: Some(a.unmet.join(", ")),
            });
        }
    }

    let mut do_not_miss: Vec<Action> = actions.iter().filter(|a| a.tier == Tier::DoNotMiss).cloned().collect();
    // Undated work sorts LAST within the dated tier — "9999" is past every real date.
    do_not_miss.sort_by(|a, b| a.by.clone().unwrap_or_else(|| "9999".into()).cmp(&b.by.clone().unwrap_or_else(|| "9999".into())));

    let mut best_return: Vec<Action> = actions.iter().filter(|a| a.tier == Tier::BestReturn).cloned().collect();
    best_return.sort_by(|a, b| {
        let ph = |x: &Action| x.per_hour.map(|m| m.minor).unwrap_or(-1);
        let w = |x: &Action| x.worth.map(|m| m.minor).unwrap_or(-1);
        ph(b).cmp(&ph(a)).then_with(|| w(b).cmp(&w(a))).then_with(|| a.title.cmp(&b.title))
    });

    Brief {
        as_of: input.as_of.to_string(),
        currency,
        headline: headline_for(input, provisional),
        do_not_miss,
        best_return,
        blocked: actions.into_iter().filter(|a| a.tier == Tier::Blocked).collect(),
        absent,
        caveats,
    }
}

/// Where you stand, in one sentence.
///
/// The runway on the LOW band is the sentence when there is one, because it is the fact every other
/// decision bends around. With no runway it says so rather than reaching for a cheerier number.
pub fn headline_for(input: &BriefInput, provisional: bool) -> String {
    let mark = if provisional { " (PROVISIONAL — see the caveats)" } else { "" };

    if let Some(r) = input.runway {
        if !r.headline.months.is_empty() {
            if !survives_horizon(&r.headline) {
                return format!(
                    "the money runs out in {} on the LOW income band — {} whole month(s) of cover, and {} more per month would close it{mark}",
                    r.headline.exhausts_in.clone().unwrap_or_default(),
                    r.headline.months_of_cover.unwrap_or(0),
                    r.headline.monthly_gap.minor
                );
            }
            let tightest = r.headline.tightest.as_ref().map(|t| t.month.clone()).unwrap_or_default();
            return format!("on the LOW income band the money holds through {}, tightest at {tightest}{mark}", r.through.clone().unwrap_or_default());
        }
    }
    if let Some(v) = input.viable {
        return format!(
            "{} a month keeps everything current, measured on {} — the worst month, not the average{mark}",
            v.headline.worst_month.minor, v.headline.worst_month_name
        );
    }
    if let Some(p) = input.position {
        return format!("net worth {}, {} liquid, {} owed as of {}{mark}", p.net_worth.minor, p.liquid.minor, p.total_debt.minor, p.as_of);
    }
    "nothing has been computed yet — ingest a statement and the rest follows".to_string()
}

/// Everything the best-return list is worth if all of it lands. CONTINGENT by construction.
pub fn total_if_everything_lands(b: &Brief) -> Money {
    money(b.best_return.iter().map(|a| a.worth.map(|m| m.minor).unwrap_or(0)).sum(), b.currency)
}

/// Hours the best-return list actually asks for — the constraint people find out about late.
pub fn total_effort_hours(b: &Brief) -> f64 {
    b.best_return.iter().map(|a| a.effort_hours.unwrap_or(0.0)).sum()
}

/// The one thing to do next, or nothing. Dated work first, exactly as the tiers say.
pub fn next_action(b: &Brief) -> Option<&Action> {
    b.do_not_miss.first().or_else(|| b.best_return.first())
}

