    #[test]
    fn a_ten_minute_phone_call_outranks_a_fifteen_thousand_dollar_grant() {
        let (p, r, pr, n, cal) = (position(true, "reconciled · 100 txns", 0), runway_out(), priority(), negotiation(), calendar());
        let t = vec![ta("o1", "newbank", "visa", 300_000, 9_000, 66_578, 57_578, true), ta("o2", "other", "store", 80_000, 2_400, 921, -1_479, false)];
        let o = vec![
            assessment("a", "SBIR Phase I", Verdict::Biddable, Some(1_500_000), Some(18_750), 80.0, true, &[]),
            assessment("c", "Big contract", Verdict::Ineligible, None, None, 100.0, false, &["past-performance"]),
        ];
        let b = build_brief(&BriefInput {
            position: Some(&p),
            runway: Some(&r),
            priority: Some(&pr),
            negotiation: Some(&n),
            transfers: Some(&t),
            opportunities: Some(&o),
            calendar: Some(&cal),
            ..BriefInput::new("2026-06-30", Currency::USD)
        });

        // THE WHOLE POINT. The bid is worth 1,500,000 — a hundred times the phone call — and it ranks
        // BELOW it, because 80 hours against half an hour is what actually decides where the next
        // hour goes. Ranking by size gets this exactly backwards.
        let order: Vec<(&str, i64)> = b.best_return.iter().map(|a| (a.id.as_str(), a.per_hour.map(|m| m.minor).unwrap_or(-1))).collect();
        assert_eq!(
            order,
            vec![("transfer:visa:o1", 57_578), ("call:visa:rate-reduction", 30_000), ("bid:a", 18_750), ("call:visa:fee-waiver", 7_000), ("pay:visa", -1), ("buffer", -1)]
        );
        // An action with no effort recorded sorts LAST rather than as zero — undefined is not free.
        assert!(b.best_return[4].per_hour.is_none());
        assert_eq!(total_if_everything_lands(&b).minor, 1_616_078);
        assert_eq!(total_effort_hours(&b), 82.0, "the constraint people find out about late");
    }

    #[test]
    fn dated_work_is_a_separate_tier_because_no_rate_makes_it_comparable() {
        let (p, r, n, cal) = (position(true, "reconciled", 0), runway_out(), negotiation(), calendar());
        let b = build_brief(&BriefInput { position: Some(&p), runway: Some(&r), negotiation: Some(&n), calendar: Some(&cal), ..BriefInput::new("2026-06-30", Currency::USD) });
        let ids: Vec<&str> = b.do_not_miss.iter().map(|a| a.id.as_str()).collect();
        // Sorted by WHEN, and the undated hardship call sorts last inside the tier.
        assert_eq!(ids, vec!["due:visa:2026-07-01:chase minimum", "due:chk:2026-07-05:RENT LANDLORD LLC", "hardship:store"]);
        // A hardship case is NOT a best-return item — ranking it per hour would bury the one thing
        // that has to happen before a missed payment.
        assert!(!b.best_return.iter().any(|a| a.id.starts_with("hardship")));
        assert!(b.do_not_miss[2].why.contains("CALL BEFORE A PAYMENT IS MISSED"));
        // Outside the horizon is absent.
        assert!(!ids.iter().any(|i| i.contains("FAR AWAY")));
        assert_eq!(next_action(&b).unwrap().id, "due:visa:2026-07-01:chase minimum");
    }

    #[test]
    fn an_assumed_due_date_makes_that_line_provisional_on_its_own() {
        let (p, cal) = (position(true, "reconciled", 0), calendar());
        let b = build_brief(&BriefInput { position: Some(&p), calendar: Some(&cal), ..BriefInput::new("2026-06-30", Currency::USD) });
