        // guessed, and the one obligation that must not be late is where that matters most.
        assert!(b.do_not_miss[0].provisional);
        assert!(b.do_not_miss[0].why.contains("the DATE is assumed, not observed"));
        assert!(!b.do_not_miss[1].provisional);
    }

    #[test]
    fn a_capability_that_never_ran_is_named_rather_than_reported_as_zero() {
        let b = build_brief(&BriefInput::new("2026-06-30", Currency::USD));
        // "$0 available in fee waivers" when the fee audit never ran is the specific lie that would
        // make somebody stop looking.
        assert_eq!(
            b.absent,
            vec![
                "obligations — no calendar was built, so nothing here knows what is due",
                "negotiate — no call list was prepared",
                "transfer — no offers were priced",
                "opportunity — no funding sources were scanned",
                "priority — nothing decided where this month's spare money goes",
