    #[test]
    fn priced_and_rejected_is_a_result_and_never_ran_is_a_gap() {
        let p = position(true, "reconciled", 0);
        let t = vec![ta("o2", "other", "store", 80_000, 2_400, 921, -1_479, false)];
        let b = build_brief(&BriefInput { position: Some(&p), transfers: Some(&t), ..BriefInput::new("2026-06-30", Currency::USD) });
        // Priced and none beat its fee: a CAVEAT, and explicitly not an absence.
        assert!(b.caveats.iter().any(|c| c.contains("NONE beat its fee — that is a result, not a gap")));
        assert!(!b.absent.iter().any(|a| a.starts_with("transfer")));
        // Not run at all: an ABSENCE, and no caveat.
        let b2 = build_brief(&BriefInput { position: Some(&p), ..BriefInput::new("2026-06-30", Currency::USD) });
        assert!(b2.absent.iter().any(|a| a.starts_with("transfer")));
        assert!(!b2.caveats.iter().any(|c| c.contains("beat its fee")));
    }

    #[test]
    fn provisional_propagates_from_the_ledger_to_every_line() {
        let p = position(false, "UNVERIFIED — nothing checked it", 2);
        let n = negotiation();
        let b = build_brief(&BriefInput { position: Some(&p), negotiation: Some(&n), ..BriefInput::new("2026-06-30", Currency::USD) });
        assert!(b.best_return.iter().all(|a| a.provisional), "the reader acts on individual LINES, not on one note at the top");
        assert_eq!(b.caveats.len(), 2);
        assert!(b.caveats[0].contains("the ledger under this was never reconciled"));
        assert!(b.caveats[1].contains("2 unresolved issue(s)"));
        assert!(b.headline.ends_with("(PROVISIONAL — see the caveats)"));
    }

