    fn the_headline_falls_back_through_runway_then_viable_then_position() {
        let r = runway_out();
        let p = position(true, "reconciled", 0);
        // The runway on the LOW band is the fact every other decision bends around.
        assert!(headline_for(&BriefInput { runway: Some(&r), ..BriefInput::new("2026-06-30", Currency::USD) }, false).starts_with("the money runs out in 2026-07 on the LOW income band"));
