    }

    #[test]
    fn something_you_cannot_bid_is_blocked_with_what_would_unblock_it() {
        let p = position(true, "reconciled", 0);
        let o = vec![assessment("c", "Big contract", Verdict::Ineligible, None, None, 100.0, false, &["past-performance"])];
        let b = build_brief(&BriefInput { position: Some(&p), opportunities: Some(&o), ..BriefInput::new("2026-06-30", Currency::USD) });
        assert_eq!(b.blocked.len(), 1);
        assert_eq!(b.blocked[0].id, "unblock:c");
        assert_eq!(b.blocked[0].blocked_by.as_deref(), Some("past-performance"));
        // Blocked work carries no worth — pricing something you cannot do would put it in the
        // ranking, which is the mistake the tier exists to avoid.
        assert!(b.blocked[0].worth.is_none() && b.blocked[0].per_hour.is_none());
        assert!(!b.best_return.iter().any(|a| a.id.starts_with("unblock")));
    }

    #[test]
    fn effort_defaults_are_named_because_they_drive_the_whole_ranking() {
        let (p, n) = (position(true, "reconciled", 0), negotiation());
        // Half an hour per call by default: 15000 becomes 30000/h.
        let b = build_brief(&BriefInput { position: Some(&p), negotiation: Some(&n), ..BriefInput::new("2026-06-30", Currency::USD) });
        assert_eq!(b.best_return[0].per_hour.unwrap().minor, 30_000);
        // Say a call takes five hours and the same action falls to 3000/h — the ranking is a
        // function of an assumption, so the assumption is an input rather than a constant.
        let slow = build_brief(&BriefInput { position: Some(&p), negotiation: Some(&n), call_hours: 5.0, ..BriefInput::new("2026-06-30", Currency::USD) });
        assert_eq!(slow.best_return[0].per_hour.unwrap().minor, 3_000);
        // Zero hours is ABSENT rather than infinite — it would sort a priceless thing first.
        let free = build_brief(&BriefInput { position: Some(&p), negotiation: Some(&n), call_hours: 0.0, ..BriefInput::new("2026-06-30", Currency::USD) });
        assert!(free.best_return.iter().all(|a| a.per_hour.is_none()));
    }
